-- Synthetic data in kino_public_test ONLY. Never run this file against hosted projects.
create function public.beta_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create table public.beta_test_fixture(family_id uuid,a uuid,b uuid,invite jsonb,session_id uuid,media_id uuid,path text);
grant select,insert on public.beta_test_fixture to authenticated;
update mv_private.beta_config set accepting_families=true;
insert into mv_private.beta_enrollments(email,can_create) select x||n||'@example.test',x='a' from generate_series(1,5) n cross join (values('a'),('b')) v(x);
insert into auth.users select ('10000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,(case when n%2=1 then 'a' else 'b' end)||((n+1)/2)||'@example.test',now() from generate_series(1,10) n;
do $$begin begin insert into auth.users values(gen_random_uuid(),'stranger@example.test',now());raise exception 'Unexpected registration';exception when insufficient_privilege then perform public.beta_assert(true,'unlisted email cannot register even with Auth signup enabled');end;end$$;
set role authenticated;
do $$declare n int;a uuid;b uuid;f uuid;i jsonb;j jsonb;sid uuid;mid uuid;path text;begin
 for n in 1..5 loop
 a:=('10000000-0000-4000-8000-'||lpad((n*2-1)::text,12,'0'))::uuid;b:=('10000000-0000-4000-8000-'||lpad((n*2)::text,12,'0'))::uuid;
 perform set_config('request.jwt.claim.sub',a::text,false);
 f:=public.kv_create_pair('Максим '||n,'Вселенная '||n);
 perform public.beta_assert(public.kv_create_pair('Повтор','')=f,'pair creation retry is idempotent '||n);
 i:=public.kv_invite('b'||n||'@example.test');
 perform set_config('request.jwt.claim.sub',b::text,false);
 j:=public.kv_pair_invitation(i->>'code',false);
 perform public.beta_assert(j->>'inviter'='Максим '||n,'invitation preview identifies actual inviter '||n);
 j:=public.kv_pair_invitation(i->>'token',true,'Оля '||n);
 perform public.beta_assert((j->>'ok')::boolean,'one-time QR token joins correct second member '||n);
 perform public.beta_assert(not(public.kv_pair_invitation(i->>'code',true,'Повтор')->>'ok')::boolean,'used invitation cannot be reused '||n);
 perform public.beta_assert((select count(*)=2 from public.mv_members),'RLS exposes only two members '||n);
 perform public.mv_apply(gen_random_uuid(),'rating','iron-man','{"score":7}',0);
 perform public.mv_impression('iron-man','Синтетическое впечатление второго участника',0);
 perform set_config('request.jwt.claim.sub',a::text,false);
 perform public.mv_apply(gen_random_uuid(),'rating','iron-man','{"score":9}',0);
 perform public.mv_impression('iron-man','Синтетическое впечатление первого участника',0);
 perform public.beta_assert((select count(*)=2 and avg(score)=8 from public.mv_ratings),'independent ratings before viewing stay isolated '||n);
 perform public.mv_apply(gen_random_uuid(),'entry','iron-man','{"watched":true,"watched_date":"2026-11-15"}',0);
 perform public.beta_assert((select count(*)=1 from public.mv_watch_requests where status='pending'),'viewing still requires partner confirmation '||n);
 perform set_config('request.jwt.claim.sub',b::text,false);
 perform public.mv_apply(gen_random_uuid(),'watch_confirm',(select id::text from public.mv_watch_requests where status='pending'),'{}',(select version from public.mv_watch_requests where status='pending'));
 perform public.beta_assert((select watched from public.mv_entries where project_id='iron-man'),'partner confirms own family viewing '||n);
 perform public.beta_assert((select xp=10 from public.mv_achievements where achievement_id='films-1'),'new pair receives canonical bronze XP '||n);
 perform public.beta_assert((select count(*)=2 from public.mv_impressions),'two private impressions isolated '||n);
 perform public.beta_assert((select count(*)=2 from public.mv_ratings),'confirmation does not alter ratings '||n);
 sid:=gen_random_uuid();mid:=gen_random_uuid();
 perform public.mv_apply(gen_random_uuid(),'session',sid::text,'{"project_id":"thor"}',0);
 path:=public.mv_prepare_media(mid,'session',sid,'image/jpeg',300000);
 insert into public.beta_test_fixture values(f,a,b,i,sid,mid,path);
 perform public.beta_assert((public.kv_storage_usage()->>'count')::int=1,'storage usage scoped to pair '||n);
 perform public.beta_assert((public.mv_export()->'members'->0->>'family_id')::uuid=f,'export contains only current pair '||n);
 end loop;
end$$;
reset role;
-- These are fake storage records, not photographs. No outbound request is made.
insert into storage.objects(bucket_id,name) select 'marvel-private',path from public.beta_test_fixture;
update public.mv_media set ready=true;
set role authenticated;
do $$declare row record;other public.beta_test_fixture;num int:=0;t text;begin
 for row in select * from public.beta_test_fixture loop
 num:=num+1;perform set_config('request.jwt.claim.sub',row.a::text,false);
 select * into other from public.beta_test_fixture where family_id<>row.family_id limit 1;
 perform public.beta_assert((select count(*)=1 from public.mv_families),'family list is isolated '||num);
 perform public.beta_assert((select count(*)=2 from public.mv_members),'membership cannot enumerate other pairs '||num);
 perform public.beta_assert((select count(*)=1 from public.mv_sessions),'session history is isolated '||num);
 perform public.beta_assert((select count(*)=1 from public.mv_media),'photo metadata is isolated '||num);
 perform public.beta_assert((select count(*)=1 from storage.objects),'authenticated storage download cannot read other paths '||num);
 perform public.beta_assert(not exists(select 1 from storage.objects where name=other.path),'forged object path is denied '||num);
 perform public.beta_assert(not exists(select 1 from public.mv_achievements where family_id<>row.family_id),'awards are isolated '||num);
 perform public.beta_assert(not exists(select 1 from public.mv_notifications where family_id<>row.family_id),'push inbox is isolated '||num);
 perform public.beta_assert(not(public.kv_pair_invitation(other.invite->>'token',false)->>'ok')::boolean,'foreign invitation is not exposed '||num);
 begin perform public.mv_apply(gen_random_uuid(),'session',other.session_id::text,'{"status":"finished"}',1);raise exception 'Expected cross-session denial';exception when insufficient_privilege then perform public.beta_assert(true,'cross-pair session write denied '||num);end;
 begin perform public.mv_prepare_media(other.media_id,'session',row.session_id,'image/jpeg',300000);raise exception 'Expected media denial';exception when insufficient_privilege then perform public.beta_assert(true,'cross-pair upload reuse denied '||num);end;
 begin update public.mv_ratings set score=10 where user_id=row.b;raise exception 'Expected direct write denial';exception when insufficient_privilege then perform public.beta_assert(true,'cannot edit partner rating directly '||num);end;
 begin perform public.mv_apply(gen_random_uuid(),'rating','thor',jsonb_build_object('score',10,'user_id',row.b),0);raise exception 'Expected identity denial';exception when insufficient_privilege then perform public.beta_assert(true,'RPC cannot forge partner identity '||num);end;
 begin update public.mv_achievements set xp=999;raise exception 'Expected XP denial';exception when insufficient_privilege then perform public.beta_assert(true,'cannot forge earned XP '||num);end;
 begin perform public.mv_apply(gen_random_uuid(),'message',gen_random_uuid()::text,'{"body":"retired"}',0);raise exception 'Expected retired feature';exception when raise_exception then if sqlerrm<>'FEATURE_RETIRED' then raise;end if;perform public.beta_assert(true,'chat server path remains retired '||num);end;
 perform public.beta_assert((public.mv_legend()->'xp_scale'->>'platinum')::int=100,'legend RPC retains canonical scale '||num);
 end loop;
end$$;
reset role;
-- Failed guessing is committed, rather than rolled back with an exception.
set role authenticated;
select set_config('request.jwt.claim.sub',(select a::text from public.beta_test_fixture limit 1),false);
do $$declare n int;reply jsonb;begin for n in 1..11 loop reply:=public.kv_pair_invitation('BAD-CODE',false);end loop;perform public.beta_assert(reply->>'error'='RATE_LIMITED','guess attempts are server rate limited');end$$;
reset role;
select public.beta_assert((select max(hits)>10 from mv_private.beta_attempts),'failed attempts persist in database');
-- Quota includes outstanding reservations; declared byte size is checked server-side.
set role authenticated;
select set_config('request.jwt.claim.sub',(select a::text from public.beta_test_fixture limit 1),false);
do $$declare n int;begin for n in 1..9 loop perform public.mv_prepare_media(gen_random_uuid(),'staged',null,'image/jpeg',400000);end loop;
 perform public.beta_assert((public.kv_storage_usage()->>'count')::int=10,'ten reservations consume the photo quota');
 begin perform public.mv_prepare_media(gen_random_uuid(),'staged',null,'image/jpeg',400000);raise exception 'Expected quota denial';exception when raise_exception then if sqlerrm<>'FAMILY_PHOTO_QUOTA' then raise;end if;perform public.beta_assert(true,'eleventh photo cannot bypass quota');end;
 begin perform public.mv_prepare_media(gen_random_uuid(),'staged',null,'image/jpeg',524289);raise exception 'Expected oversized denial';exception when raise_exception then if sqlerrm<>'INVALID_IMAGE' then raise;end if;perform public.beta_assert(true,'oversized photo rejected by SQL');end;
 perform public.kv_set_name('Саша 🌙');perform public.beta_assert((select display_name='Саша 🌙' from public.mv_members where user_id=auth.uid()),'names use actual user-provided Unicode');
 perform public.kv_deletion_request('account');perform public.kv_deletion_request('account');perform public.beta_assert((select count(*)=1 from public.kv_deletion_requests),'deletion request is idempotent and honest about pending processing');
end$$;
reset role;
select public.beta_assert((select count(*)=5 from public.mv_families),'five synthetic pairs remain independent');
select public.beta_assert((select count(*)=10 from public.mv_members),'every pair has exactly two accounts');
select public.beta_assert((select count(*)=82 from mv_private.trophy_presentation),'all 82 trophy definitions retained');
select public.beta_assert(not has_function_privilege('authenticated','public.mv_create_family()','execute'),'old bootstrap RPC disabled');
select public.beta_assert(not has_function_privilege('authenticated','public.mv_invite(text)','execute'),'old email invitation RPC disabled');
select public.beta_assert(not has_function_privilege('authenticated','mv_private.beta_admin_report()','execute'),'admin report unavailable to users');
select public.beta_assert(not has_table_privilege('authenticated','mv_private.pair_invitations','select'),'invitation secrets unavailable to clients');
select public.beta_assert(not has_function_privilege('anon','public.kv_pair_invitation(text,boolean,text)','execute'),'invitation requires authenticated identity');
select public.beta_assert((select count(*)=0 from mv_private.bootstrap),'no source-family bootstrap was copied');
-- Expired/revoked links and explicit second-member confirmation.
insert into mv_private.beta_enrollments(email,can_create) values('a6@example.test',true),('b6@example.test',false),('third@example.test',false);
insert into auth.users values('10000000-0000-4000-8000-000000000011','a6@example.test',now()),('10000000-0000-4000-8000-000000000012','b6@example.test',now()),('10000000-0000-4000-8000-000000000013','third@example.test',now());
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000011',false);
select public.kv_create_pair('Первый','Проверки приглашений');
insert into public.beta_test_fixture(family_id,a,b,invite) select family_id,user_id,'10000000-0000-4000-8000-000000000012'::uuid,public.kv_invite('b6@example.test') from public.mv_members where user_id=auth.uid();
reset role;
update mv_private.pair_invitations set expires_at=now()-interval '1 second' where family_id=(select family_id from public.beta_test_fixture where a='10000000-0000-4000-8000-000000000011');
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000012',false);
select public.beta_assert(not(public.kv_pair_invitation((select invite->>'token' from public.beta_test_fixture where b=auth.uid()),true,'Второй')->>'ok')::boolean,'expired invitation cannot join');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000011',false);
select public.kv_revoke_invite((public.kv_invite('b6@example.test')->>'id')::uuid);
select public.beta_assert((select count(*)=1 from public.mv_members),'preview and revocation never silently connect partner');
reset role;
-- Prepare a fresh invitation for the two-connection race performed by the script.
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000011',false);
update public.beta_test_fixture set invite=public.kv_invite('b6@example.test') where a='10000000-0000-4000-8000-000000000011';
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000013',false);
select public.beta_assert(not(public.kv_pair_invitation((select invite->>'token' from public.beta_test_fixture where a='10000000-0000-4000-8000-000000000011'),true,'Третий')->>'ok')::boolean,'stolen code cannot be used by different confirmed email');
reset role;
select public.beta_assert(not has_function_privilege('anon','public.mv_prepare_media(uuid,text,uuid,text,integer)','execute'),'anonymous upload reservation is denied');
